from collections import defaultdict
from contextlib import contextmanager
import fcntl
import os
import re
import shutil
import subprocess
import sys
import time
import zipfile
import zlib

from openlibrary.coverstore import config, db


SIZES = ('', 's', 'm', 'l')
ITEM_SIZE = 1_000_000
BATCH_SIZE = 10_000
MEMBER_RE = re.compile(r'^(\d{10})(?:-([SML]))?\.([A-Za-z0-9]+)$')


def _cover_id(value):
    if isinstance(value, bool) or not str(value).isdigit() or int(value) >= 10**10:
        raise ValueError(f'Invalid ten-digit cover ID: {value!r}')
    return int(value)


def _size(value):
    value = value.lower()
    if value not in SIZES:
        raise ValueError(f'Invalid cover size: {value!r}')
    return value


def _extension(value):
    value = value.lstrip('.')
    if not value.isalnum():
        raise ValueError(f'Invalid file extension: {value!r}')
    return value


def _member_parts(name):
    match = MEMBER_RE.fullmatch(name)
    if not match:
        raise ValueError(f'Invalid ZIP member name: {name!r}')
    cover_id, suffix, ext = match.groups()
    return int(cover_id), (suffix or '').lower(), ext


class Cover:
    """A database cover record and its local image variants."""

    def __init__(self, attributes):
        self.__dict__.update(attributes)

    @staticmethod
    def id_to_item_and_batch_id(cover_id):
        padded = f'{_cover_id(cover_id):010d}'
        return padded[:4], padded[4:6]

    @staticmethod
    def get_cover_url(cover_id, size='', ext='jpg', protocol='https'):
        cover_id = _cover_id(cover_id)
        size, ext = _size(size), _extension(ext)
        if protocol not in ('http', 'https'):
            raise ValueError(f'Invalid protocol: {protocol!r}')
        item_id, batch_id = Cover.id_to_item_and_batch_id(cover_id)
        prefix = f'{size}_' if size else ''
        item = f'{prefix}covers_{item_id}'
        suffix = f'-{size.upper()}' if size else ''
        return (
            f'{protocol}://archive.org/download/{item}/{item}_{batch_id}.zip/'
            f'{cover_id:010d}{suffix}.{ext}'
        )

    def local_files(self):
        """Yield (size, ZIP member, source path) for each image variant."""
        cover_id = _cover_id(self.id)
        for size in SIZES:
            field = f'filename_{size}' if size else 'filename'
            name = f'{cover_id:010d}{"-" + size.upper() if size else ""}.jpg'
            filename = getattr(self, field, None)
            path = (
                os.path.join(config.data_root, 'localdisk', filename)
                if filename and '://' not in filename and ':' not in filename
                else None
            )
            yield size, name, path

    def has_valid_files(self):
        return all(path and os.path.isfile(path) for _, _, path in self.local_files())

    def delete_files(self):
        for _, _, path in self.local_files():
            if path and os.path.isfile(path):
                os.remove(path)


class CoverDB:
    """Database access for pending, failed, and completed cover batches."""

    def __init__(self):
        self.db = db.getdb()

    @staticmethod
    def _get_batch_end_id(start_id):
        return (_cover_id(start_id) // BATCH_SIZE + 1) * BATCH_SIZE - 1

    def get_unarchived(self, limit=10_000):
        return list(self.db.select(
            'cover', where='archived=$false AND failed=$false AND uploaded=$false',
            order='id', limit=limit, vars={'false': False},
        ))

    def get_unarchived_batch(self, item_id, batch_id):
        start_id = int(item_id) * ITEM_SIZE + int(batch_id) * BATCH_SIZE
        return list(self.db.select(
            'cover',
            where='id >= $start_id AND id <= $end_id AND archived=$false '
            'AND failed=$false AND uploaded=$false',
            order='id', vars={
                'start_id': start_id,
                'end_id': self._get_batch_end_id(start_id), 'false': False,
            },
        ))

    def get_archived_batch(self, item_id, batch_id, uploaded=False):
        start_id = int(item_id) * ITEM_SIZE + int(batch_id) * BATCH_SIZE
        return list(self.db.select(
            'cover',
            where='id >= $start_id AND id <= $end_id AND archived=$true '
            'AND failed=$false AND uploaded=$uploaded',
            order='id', vars={
                'start_id': start_id,
                'end_id': self._get_batch_end_id(start_id),
                'true': True, 'false': False, 'uploaded': uploaded,
            },
        ))

    def get_failed(self, limit=10_000):
        return list(self.db.select('cover', where='failed=$true', order='id',
                                   limit=limit, vars={'true': True}))

    def get_completed_batches(self):
        rows = self.db.select('cover', what='id', where='uploaded=$true',
                              vars={'true': True})
        return sorted({Cover.id_to_item_and_batch_id(row.id) for row in rows})

    def mark_archived(self, cover_id):
        self.db.update('cover', where='id=$cover_id AND archived=$false AND failed=$false',
                       vars={'cover_id': cover_id, 'false': False}, archived=True)

    def mark_failed(self, cover_id):
        self.db.update('cover', where='id=$cover_id AND uploaded=$false',
                       vars={'cover_id': cover_id, 'false': False}, failed=True)

    @staticmethod
    def update_completed_batch(item_id, batch_id, ext='jpg'):
        """Atomically assign canonical URLs and uploaded=true to eligible rows.

        Returns the old records so source images can be removed after commit.
        A repeated call leaves already completed rows untouched.
        """
        ext = _extension(ext)
        item_id, batch_id = Batch(item_id, batch_id)._norm_ids()
        cover_db = CoverDB()
        rows = cover_db.get_archived_batch(item_id, batch_id, uploaded=False)
        transaction = cover_db.db.transaction()
        try:
            for row in rows:
                cover_db.db.update(
                    'cover',
                    where='id=$cover_id AND archived=$true AND failed=$false '
                    'AND uploaded=$false',
                    vars={'cover_id': row.id, 'true': True, 'false': False},
                    filename=Cover.get_cover_url(row.id, ext=ext),
                    filename_s=Cover.get_cover_url(row.id, 's', ext),
                    filename_m=Cover.get_cover_url(row.id, 'm', ext),
                    filename_l=Cover.get_cover_url(row.id, 'l', ext),
                    uploaded=True,
                )
        except Exception:
            transaction.rollback()
            raise
        else:
            transaction.commit()
        return rows


class Batch:
    """One ten-thousand-cover ZIP batch within a million-cover item."""

    def __init__(self, item_id, batch_id, size=None):
        self.item_id, self.batch_id = item_id, batch_id
        self.size = None if size is None else _size(size)
        self._lock_depth = 0
        self._verified = False
        self._norm_ids()

    def _norm_ids(self):
        item_id, batch_id = int(self.item_id), int(self.batch_id)
        if not 0 <= item_id <= 9999 or not 0 <= batch_id <= 99:
            raise ValueError('Item ID must be 0..9999 and batch ID 0..99')
        return f'{item_id:04d}', f'{batch_id:02d}'

    @classmethod
    def get_relpath(cls, item_id, batch_id, size='', ext='zip'):
        item_id, batch_id = cls(item_id, batch_id, size)._norm_ids()
        size, ext = _size(size), _extension(ext)
        prefix = f'{size}_' if size else ''
        item = f'{prefix}covers_{item_id}'
        return os.path.join('items', item, f'{item}_{batch_id}.{ext}')

    @classmethod
    def get_abspath(cls, item_id, batch_id, size='', ext='zip'):
        return os.path.join(config.data_root,
                            cls.get_relpath(item_id, batch_id, size, ext))

    def item_name(self, size=''):
        item_id, _ = self._norm_ids()
        prefix = f'{_size(size)}_' if size else ''
        return f'{prefix}covers_{item_id}'

    def _paths(self):
        return {size: self.get_abspath(self.item_id, self.batch_id, size)
                for size in SIZES}

    @contextmanager
    def lock(self):
        """A nonblocking item lock prevents concurrent batch or item writers."""
        if self._lock_depth:
            self._lock_depth += 1
            try:
                yield
            finally:
                self._lock_depth -= 1
            return
        item_id, _ = self._norm_ids()
        lock_dir = os.path.join(config.data_root, 'items', '.locks')
        os.makedirs(lock_dir, exist_ok=True)
        with open(os.path.join(lock_dir, f'covers_{item_id}.lock'), 'a+b') as file:
            try:
                fcntl.flock(file, fcntl.LOCK_EX | fcntl.LOCK_NB)
            except BlockingIOError as exc:
                raise RuntimeError(f'Cover item {item_id} is already being archived') from exc
            self._lock_depth = 1
            try:
                yield
            finally:
                self._lock_depth = 0
                fcntl.flock(file, fcntl.LOCK_UN)

    def process_pending(self, upload=False, finalize=False, test=True, uploader=None):
        """Upload staged ZIPs and finalize only after all four are verified."""
        uploader = uploader or Uploader()
        sizes = SIZES if self.size is None else (self.size,)
        with self.lock():
            paths = self._paths()
            present = {size: os.path.isfile(path) for size, path in paths.items()}
            if not any(present[size] for size in sizes):
                return False
            for size in sizes:
                if not present[size]:
                    continue
                item, filename = self.item_name(size), os.path.basename(paths[size])
                verified = uploader.is_uploaded(item, filename)
                if not verified and upload and not test:
                    uploader.upload(item, [paths[size]])
                    verified = uploader.is_uploaded(item, filename)
                if not verified:
                    return False
            if not finalize:
                return True
            if not all(present.values()):
                return False
            for size in SIZES:
                if size not in sizes and not uploader.is_uploaded(
                    self.item_name(size), os.path.basename(paths[size])
                ):
                    return False
            self._verified = True
            try:
                return self.finalize(test=test)
            finally:
                self._verified = False

    def finalize(self, start_id=None, test=False):
        """Reconcile the verified batch, then delete staging ZIPs and sources."""
        with self.lock():
            paths = self._paths()
            if not all(os.path.isfile(path) for path in paths.values()):
                return False
            if not self._verified:
                for size, path in paths.items():
                    if not Uploader.is_uploaded(self.item_name(size), os.path.basename(path)):
                        return False
            item_id, batch_id = self._norm_ids()
            rows = CoverDB().get_archived_batch(item_id, batch_id, uploaded=False)
            if not rows:
                return False
            for size, path in paths.items():
                suffix = f'-{size.upper()}' if size else ''
                expected = {f'{row.id:010d}{suffix}.jpg' for row in rows}
                with zipfile.ZipFile(path) as zipped:
                    names = zipped.namelist()
                    if set(names) != expected or len(names) != len(expected):
                        return False
                    if zipped.testzip() is not None:
                        return False
            if test:
                return True
            prior_rows = CoverDB.update_completed_batch(item_id, batch_id)
            for row in prior_rows:
                Cover(row).delete_files()
            for path in paths.values():
                os.remove(path)
            return True


def count_files_in_zip(filepath):
    """Count JPEG members without relying on shell output parsing."""
    with zipfile.ZipFile(filepath) as zipped:
        return sum(name.lower().endswith('.jpg') for name in zipped.namelist())


def open_zipfile(name):
    cover_id, size, _ = _member_parts(name)
    item_id, batch_id = Cover.id_to_item_and_batch_id(cover_id)
    path = Batch.get_abspath(item_id, batch_id, size)
    os.makedirs(os.path.dirname(path), exist_ok=True)
    return zipfile.ZipFile(path, 'a', compression=zipfile.ZIP_STORED, allowZip64=True)


def get_zipfile(name):
    """Open the ZIP for a member; the caller owns and must close the handle."""
    return open_zipfile(name)


class ZipManager:
    """Write each uncompressed ZIP member once, including across retries."""

    def __init__(self):
        self.zipfiles = {}
        self.members = {}

    def add_file(self, name, filepath, mtime):
        cover_id, size, ext = _member_parts(name)
        item_id, batch_id = Cover.id_to_item_and_batch_id(cover_id)
        path = Batch.get_abspath(item_id, batch_id, size)
        if path not in self.zipfiles:
            zipped = open_zipfile(name)
            self.zipfiles[path] = zipped
            self.members[path] = {info.filename: info for info in zipped.infolist()}
        zipped = self.zipfiles[path]
        if name in self.members[path]:
            info = self.members[path][name]
            crc = 0
            with open(filepath, 'rb') as source:
                for chunk in iter(lambda: source.read(1024 * 1024), b''):
                    crc = zlib.crc32(chunk, crc)
            if info.file_size != os.path.getsize(filepath) or info.CRC != crc:
                raise ValueError(f'Existing ZIP member differs from source: {name}')
        else:
            info = zipfile.ZipInfo(name, time.gmtime(max(mtime, 315532800))[:6])
            info.compress_type = zipfile.ZIP_STORED
            info.external_attr = 0o644 << 16
            with open(filepath, 'rb') as source, zipped.open(info, 'w') as target:
                shutil.copyfileobj(source, target)
            self.members[path][name] = zipped.getinfo(name)
        return Cover.get_cover_url(cover_id, size, ext)

    def close(self):
        for zipped in self.zipfiles.values():
            zipped.close()
        self.zipfiles.clear()
        self.members.clear()


class Uploader:
    """Wrapper around the installed Internet Archive command line tool."""

    @staticmethod
    def upload(itemname: str, filepaths: list[str]):
        if not filepaths:
            return None
        return subprocess.run(
            ['ia', 'upload', itemname, *filepaths, '--retries', '10'],
            text=True, capture_output=True, check=True,
        )

    @staticmethod
    def is_uploaded(item: str, zip_filename: str, verbose: bool = False) -> bool:
        result = subprocess.run(
            ['ia', 'list', item], text=True, capture_output=True, check=True,
        )
        found = zip_filename in {line.strip() for line in result.stdout.splitlines()}
        if verbose:
            print(f'{item}/{zip_filename}: {"uploaded" if found else "missing"}')
        return found


def is_uploaded(item: str, zip_filename: str) -> bool:
    """Compatibility entry point for the former module-level check."""
    return Uploader.is_uploaded(item, zip_filename)


def audit(group_id, chunk_ids=(0, 100), sizes=SIZES) -> None:
    """Report ZIP batches missing from their Internet Archive items."""
    group_id = Batch(group_id, 0)._norm_ids()[0]
    scope = range(*(chunk_ids if isinstance(chunk_ids, tuple) else (0, chunk_ids)))
    for size in sizes:
        size = _size(size)
        item = Batch(group_id, 0).item_name(size)
        missing = []
        sys.stdout.write(f'\n{size or "full"}: ')
        for batch_id in scope:
            name = os.path.basename(Batch.get_relpath(group_id, batch_id, size))
            uploaded = Uploader.is_uploaded(item, name)
            sys.stdout.write('.' if uploaded else 'X')
            if not uploaded:
                missing.append(name)
        sys.stdout.write('\n')
        if missing:
            print(f'Missing from {item}: {", ".join(missing)}')


def archive(test=True):
    """Stage up to 10,000 unarchived covers, retaining sources until verified."""
    cover_db = CoverDB()
    candidates = cover_db.get_unarchived(limit=10_000)
    groups = defaultdict(list)
    for row in candidates:
        groups[Cover.id_to_item_and_batch_id(row.id)].append(row.id)

    for (item_id, batch_id), selected_ids in sorted(groups.items()):
        batch = Batch(item_id, batch_id)
        with batch.lock():
            # Re-read under the item lock; the initial query may now be stale.
            rows = [row for row in cover_db.get_unarchived_batch(item_id, batch_id)
                    if row.id in selected_ids]
            if test:
                for row in rows:
                    print(f'Would archive cover {row.id}')
                continue
            manager = ZipManager()
            staged = []
            try:
                for row in rows:
                    cover = Cover(row)
                    if not cover.has_valid_files():
                        cover_db.mark_failed(row.id)
                        print(f'Missing image file for {row.id:010d}')
                        continue
                    created = row.created
                    if isinstance(created, str):
                        from infogami.infobase import utils

                        created = utils.parse_datetime(created)
                    timestamp = time.mktime(created.timetuple())
                    for _, name, path in cover.local_files():
                        manager.add_file(name, path, timestamp)
                    staged.append(row.id)
            finally:
                manager.close()
            # No row points at an incomplete ZIP. A crash before this step is
            # retried by ZipManager, which checks existing member content.
            for cover_id in staged:
                cover_db.mark_archived(cover_id)
    return len(candidates)

