class Batch:
    """One ten-thousand-cover ZIP batch within a million-cover item."""

    def __init__(self, item_id, batch_id, size=None):
        self.item_id, self.batch_id = item_id, batch_id
        self.size = None if size is None else _size(size)
        self._lock_depth = 0
        self._verified = False
        self._norm_ids()

    def _norm_ids(self):
        item_id, batch_id = int(self.item_id), int(self.batch_id)
        if not 0 <= item_id <= 9999 or not 0 <= batch_id <= 99:
            raise ValueError('Item ID must be 0..9999 and batch ID 0..99')
        return f'{item_id:04d}', f'{batch_id:02d}'

    @classmethod
    def get_relpath(cls, item_id, batch_id, size='', ext='zip'):
        item_id, batch_id = cls(item_id, batch_id, size)._norm_ids()
        size, ext = _size(size), _extension(ext)
        prefix = f'{size}_' if size else ''
        item = f'{prefix}covers_{item_id}'
        return os.path.join('items', item, f'{item}_{batch_id}.{ext}')

    @classmethod
    def get_abspath(cls, item_id, batch_id, size='', ext='zip'):
        return os.path.join(config.data_root,
                            cls.get_relpath(item_id, batch_id, size, ext))

    def item_name(self, size=''):
        item_id, _ = self._norm_ids()
        prefix = f'{_size(size)}_' if size else ''
        return f'{prefix}covers_{item_id}'

    def _paths(self):
        return {size: self.get_abspath(self.item_id, self.batch_id, size)
                for size in SIZES}

    @contextmanager
    def lock(self):
        """A nonblocking item lock prevents concurrent batch or item writers."""
        if self._lock_depth:
            self._lock_depth += 1
            try:
                yield
            finally:
                self._lock_depth -= 1
            return
        item_id, _ = self._norm_ids()
        lock_dir = os.path.join(config.data_root, 'items', '.locks')
        os.makedirs(lock_dir, exist_ok=True)
        with open(os.path.join(lock_dir, f'covers_{item_id}.lock'), 'a+b') as file:
            try:
                fcntl.flock(file, fcntl.LOCK_EX | fcntl.LOCK_NB)
            except BlockingIOError as exc:
                raise RuntimeError(f'Cover item {item_id} is already being archived') from exc
            self._lock_depth = 1
            try:
                yield
            finally:
                self._lock_depth = 0
                fcntl.flock(file, fcntl.LOCK_UN)

    def process_pending(self, upload=False, finalize=False, test=True, uploader=None):
        """Upload staged ZIPs and finalize only after all four are verified."""
        uploader = uploader or Uploader()
        sizes = SIZES if self.size is None else (self.size,)
        with self.lock():
            paths = self._paths()
            present = {size: os.path.isfile(path) for size, path in paths.items()}
            if not any(present[size] for size in sizes):
                return False
            for size in sizes:
                if not present[size]:
                    continue
                item, filename = self.item_name(size), os.path.basename(paths[size])
                verified = uploader.is_uploaded(item, filename)
                if not verified and upload and not test:
                    uploader.upload(item, [paths[size]])
                    verified = uploader.is_uploaded(item, filename)
                if not verified:
                    return False
            if not finalize:
                return True
            if not all(present.values()):
                return False
            for size in SIZES:
                if size not in sizes and not uploader.is_uploaded(
                    self.item_name(size), os.path.basename(paths[size])
                ):
                    return False
            self._verified = True
            try:
                return self.finalize(test=test)
            finally:
                self._verified = False

    def finalize(self, start_id=None, test=False):
        """Reconcile the verified batch, then delete staging ZIPs and sources."""
        with self.lock():
            paths = self._paths()
            if not all(os.path.isfile(path) for path in paths.values()):
                return False
            if not self._verified:
                for size, path in paths.items():
                    if not Uploader.is_uploaded(self.item_name(size), os.path.basename(path)):
                        return False
            item_id, batch_id = self._norm_ids()
            rows = CoverDB().get_archived_batch(item_id, batch_id, uploaded=False)
            if not rows:
                return False
            for size, path in paths.items():
                suffix = f'-{size.upper()}' if size else ''
                expected = {f'{row.id:010d}{suffix}.jpg' for row in rows}
                with zipfile.ZipFile(path) as zipped:
                    names = zipped.namelist()
                    if set(names) != expected or len(names) != len(expected):
                        return False
                    if zipped.testzip() is not None:
                        return False
            if test:
                return True
            prior_rows = CoverDB.update_completed_batch(item_id, batch_id)
            for row in prior_rows:
                Cover(row).delete_files()
            for path in paths.values():
                os.remove(path)
            return True


