        item_id, batch_id = self._norm_ids()
        return os.path.join(config.data_root, 'items', '.manifests',
                            f'covers_{item_id}_{batch_id}.json')

    def _save_cleanup_manifest(self, rows):
        """Keep source names through a crash after the DB URL update."""
        path = self._manifest_path()
        os.makedirs(os.path.dirname(path), exist_ok=True)
        sources = [
            os.path.relpath(source, config.data_root)
            for row in rows for _, _, source in Cover(row).local_files() if source
        ]
        with tempfile.NamedTemporaryFile('w', dir=os.path.dirname(path),
                                         delete=False) as file:
            temp_path = file.name
            json.dump({'sources': sources}, file)
            file.flush()
            os.fsync(file.fileno())
        os.replace(temp_path, path)

    def _cleanup_completed(self):
        """Idempotently remove local files recorded before DB finalization."""
        manifest = self._manifest_path()
        if not os.path.isfile(manifest):
            return
        with open(manifest) as file:
            sources = json.load(file)['sources']
        local_root = os.path.realpath(os.path.join(config.data_root, 'localdisk'))
        for source in sources:
            path = os.path.realpath(os.path.join(config.data_root, source))
            if os.path.commonpath((local_root, path)) != local_root:
                raise ValueError(f'Invalid cleanup path: {source!r}')
            if os.path.isfile(path):
                os.remove(path)
        for path in self._paths().values():
            if os.path.isfile(path):
